    # ------------------------------------------------------------------
    # Bucket classifiers
    # ------------------------------------------------------------------

    @staticmethod
    def heat_bucket(percent: int) -> str:
        """Classify a utilization percentage into a heatmap bucket."""
        if percent < HEAT_LOW:
            return "low"
        if percent < HEAT_MID:
            return "mid"
        if percent <= HEAT_HIGH:
            return "high"
        return "over"

    @staticmethod
    def gesamt_bucket(free_days: float) -> str:
        """Classify free days into a gesamt bucket."""
        # Free days come from float subtraction (e.g. 5 - 0.5 - 4.3 - 0.2), so
        # compare on a rounded value to keep "exactly booked" in "neutral".
        free_days = round(free_days, FREE_DAYS_PRECISION)
        if free_days > 1.0:
            return "available"
        if free_days > 0.0:
            return "balanced"
        if free_days == 0.0:
            return "neutral"
        if free_days >= -1.0:
            return "tight"
        return "over"

    @staticmethod
    def project_heat_bucket(allocated: float) -> str:
        """Classify project allocation into a bucket."""
        if allocated <= 0:
            return "low"
        if allocated <= PROJECT_ALLOC_MID:
            return "mid"
        if allocated <= PROJECT_ALLOC_HIGH:
            return "high"
        return "over"

    # ------------------------------------------------------------------
    # Holiday + workload helpers (shared work-days computation)
    # ------------------------------------------------------------------

    @staticmethod
    def holidays_in_week(
        holiday_dates: set[date] | frozenset[date] | None,
        week_start: date,
def _today() -> date:
    return dt.datetime.now(tz=UTC).date()


def _monday(d: date) -> date:
    return d - timedelta(days=d.weekday())


def _week_label(week_start: date) -> str:
    return f"KW{week_start.isocalendar().week:02d}"


_MONTH_NAMES = (
    "Jan",
    "Feb",
    "Mär",
    "Apr",
    "Mai",
    "Jun",
    "Jul",
    "Aug",
    "Sep",
    "Okt",
    "Nov",
    "Dez",
)


def _month_label(d: date) -> str:
    return _MONTH_NAMES[d.month - 1]


def _build_week_grid(today: date, back: int, forward: int) -> list[date]:
    """Return a list of Monday-aligned week_starts spanning [back, forward)."""
    start = _monday(today) - timedelta(weeks=back)
    return [start + timedelta(weeks=i) for i in range(back + forward)]


def _heat_bucket(percent: int) -> str:
    return UtilizationService.heat_bucket(percent)


def _spent_amount(row: _ProjectRow) -> int:
    """Absolute spend; ``row.spent`` is the latest ``budget_spent`` percentage."""
    return round(row.budget * row.spent / 100)

